final class FakeTaskApp extends TaskApplicationService{public function __construct(){}public bool$explode=false;public function list(int$u,array$q):array{if($this->explode)throw new RuntimeException('SELECT secret FROM table');if(($q['status']??'')==='bad')throw new TaskValidationException('status_invalid');if((int)($q['limit']??25)>100)throw new TaskValidationException('pagination_invalid');return['tasks'=>[['public_id'=>'00000000-0000-4000-8000-000000000000']],'total'=>1,'limit'=>25,'offset'=>0];}public function detail(int$u,string$p):array{if($p==='other')throw new TaskNotFoundException('not_found');return['task'=>['public_id'=>$p],'plan'=>['planned'=>false,'steps_count'=>0],'steps'=>[],'dependencies'=>[],'executions'=>[['id'=>17,'trace_id'=>null]],'events'=>[],'artifacts'=>[]];}public function create(int$u,array$d):array{return['created'=>!($d['existing']??false),'task'=>['public_id'=>'00000000-0000-4000-8000-000000000000']];}public function cancel(int$u,array$d):array{if(($d['lock_version']??0)!==1)throw new TaskConcurrencyException('concurrency_conflict');return['task'=>['status'=>'cancelled']];}public function approve(int$u,array$d):array{if(($d['public_id']??'')==='other')throw new TaskNotFoundException('not_found');if(!array_key_exists('lock_version',$d))throw new TaskValidationException('lock_version_invalid');if($d['lock_version']!==1)throw new TaskConcurrencyException('concurrency_conflict');return['task'=>['status'=>'ready','lock_version'=>2]];}public function reject(int$u,array$d):array{if(($d['lock_version']??null)!==1)throw new TaskConcurrencyException('concurrency_conflict');return['task'=>['status'=>'cancelled']];}public function approveTool(int$u,array$d):array{return$this->tool($d,'approved');}public function rejectTool(int$u,array$d):array{return$this->tool($d,'rejected');}private function tool(array$d,string$decision):array{if(($d['public_id']??'')==='other')throw new TaskNotFoundException('not_found');if(($d['lock_version']??null)!==2)throw new TaskConcurrencyException('step_concurrency_conflict');if(preg_match('/^[a-f0-9]{64}$/D',(string)($d['fingerprint']??''))!==1)throw new TaskValidationException('tool_approval_fingerprint_invalid');return['task'=>['public_id'=>$d['public_id'],'status'=>$decision==='approved'?'ready':'cancelled','lock_version'=>3],'step'=>['step_key'=>$d['step_key'],'status'=>$decision==='approved'?'ready':'cancelled','lock_version'=>3],'decision'=>$decision];}public function retry(int$u,array$d):array{if(($d['state']??'failed')!=='failed')throw new TaskTransitionException('transition_invalid');return['task'=>['status'=>'ready']];}}
final class ApiTest{private int$p=0,$f=0;public function run():int{$a=new FakeTaskApp();$_SESSION=['csrf_token'=>'token'];$this->eq(401,(new TaskApiController($a,0,true))->handle('GET',['action'=>'list'],[])->status,'sin sesión');$c=new TaskApiController($a,1,true);$this->eq(200,$c->handle('GET',['action'=>'list'],[])->status,'GET sin CSRF');$this->eq(403,$c->handle('POST',[],['action'=>'create'],[])->status,'POST sin CSRF');$h=['x-csrf-token'=>'token'];$this->eq(201,$c->handle('POST',[],['action'=>'create'],$h)->status,'create');$this->eq(false,$c->handle('POST',[],['action'=>'create','existing'=>true],$h)->body['created'],'idempotencia');$this->eq(200,$c->handle('GET',['action'=>'detail','task'=>'00000000-0000-4000-8000-000000000000'],[])->status,'detail public_id');$this->eq(404,$c->handle('GET',['action'=>'detail','task'=>'other'],[])->status,'otro usuario no revelado');$this->eq(409,$c->handle('POST',[],['action'=>'cancel','lock_version'=>0],$h)->status,'lock obsoleto');$this->eq(200,$c->handle('POST',[],['action'=>'cancel','lock_version'=>1],$h)->status,'cancel');$this->eq(422,$c->handle('POST',[],['action'=>'approve','public_id'=>'ok'],$h)->status,'approve exige lock');$this->eq(404,$c->handle('POST',[],['action'=>'approve','public_id'=>'other','lock_version'=>1],$h)->status,'approve ownership');$this->eq(200,$c->handle('POST',[],['action'=>'approve','public_id'=>'ok','lock_version'=>1],$h)->status,'approve waiting_user');$this->eq(409,$c->handle('POST',[],['action'=>'approve','public_id'=>'ok','lock_version'=>0],$h)->status,'approve lock obsoleto');$this->eq(200,$c->handle('POST',[],['action'=>'reject','public_id'=>'ok','lock_version'=>1],$h)->status,'reject waiting_user');$fingerprint=str_repeat('a',64);$tool=['public_id'=>'ok','step_key'=>'write','lock_version'=>2,'fingerprint'=>$fingerprint];$this->eq(403,$c->handle('POST',[],['action'=>'approve_tool']+$tool,[])->status,'approve_tool exige CSRF');$this->eq(200,$c->handle('POST',[],['action'=>'approve_tool']+$tool,$h)->status,'approve_tool seguro');$this->eq('approved',$c->handle('POST',[],['action'=>'approve_tool']+$tool,$h)->body['decision'],'approve_tool devuelve DTO mínimo');$this->eq(200,$c->handle('POST',[],['action'=>'reject_tool']+$tool,$h)->status,'reject_tool seguro');$this->eq(422,$c->handle('POST',[],['action'=>'approve_tool','public_id'=>'ok','step_key'=>'write','lock_version'=>2,'fingerprint'=>'bad'],$h)->status,'fingerprint inválido');$this->eq(404,$c->handle('POST',[],['action'=>'approve_tool']+array_replace($tool,['public_id'=>'other']),$h)->status,'tool approval ownership');$this->eq(409,$c->handle('POST',[],['action'=>'approve_tool']+array_replace($tool,['lock_version'=>1]),$h)->status,'tool approval lock obsoleto');$this->eq(200,$c->handle('POST',[],['action'=>'retry','state'=>'failed'],$h)->status,'retry failed');$this->eq(409,$c->handle('POST',[],['action'=>'retry','state'=>'completed'],$h)->status,'retry completed');$this->eq(422,$c->handle('GET',['action'=>'list','status'=>'bad'],[])->status,'status inválido');$this->eq(422,$c->handle('GET',['action'=>'list','limit'=>101],[])->status,'limit inválido');$detail=$c->handle('GET',['action'=>'detail','task'=>'00000000-0000-4000-8000-000000000000'],[])->body;$this->ok(!str_contains(json_encode($detail),'lease_token'),'sin lease_token');$this->ok(isset($detail['task'],$detail['plan'],$detail['steps'],$detail['dependencies'],$detail['executions'],$detail['events'],$detail['artifacts'])&&$detail['artifacts']===[],'detail conserva colecciones y artifacts vacío estable');$a->explode=true;$r=$c->handle('GET',['action'=>'list'],[]);$this->eq(500,$r->status,'error interno');$this->ok(!str_contains(json_encode($r->body),'SELECT'),'sin SQL');$this->eq(404,(new TaskApiController($a,1,false))->handle('POST',[],['action'=>'create'],$h)->status,'flag off');echo"Resultado: {$this->p} passed, {$this->f} failed\n";echo"SKIP integración MySQL: no hay TASK_TEST_DB_* configurado.\n";return$this->f?1:0;}private function eq($e,$v,$n){$this->ok($e===$v,$n);}private function ok($v,$n){echo($v?'PASS ':'FAIL ').$n."\n";$v?$this->p++:$this->f++;}}exit((new ApiTest())->run());
